// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ExactBalanceVault {
    mapping(address => uint256) public deposits;
    uint256 public totalDeposits;

    function deposit() external payable {
        deposits[msg.sender] += msg.value;
        totalDeposits += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(address(this).balance == totalDeposits, "balance mismatch");
        require(deposits[msg.sender] >= amount, "insufficient deposit");
        deposits[msg.sender] -= amount;
        totalDeposits -= amount;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "transfer failed");
    }
}

contract SurplusAwareVault {
    uint256 public totalLiabilities;

    function isSolvent() external view returns (bool) {
        return address(this).balance >= totalLiabilities;
    }

    function reconcileSurplus() external {
        if (address(this).balance > totalLiabilities) {
            uint256 surplus = address(this).balance - totalLiabilities;
            totalLiabilities += surplus;
        }
    }
}

contract ForcedEtherSender {
    constructor() payable {}

    function force(address payable recipient) external payable {
        selfdestruct(recipient);
    }
}
